import { afterAll, beforeAll, expect, test } from 'bun:test'
import { spawnSync } from 'node:child_process'
import { mkdir, rm, writeFile } from 'node:fs/promises'
import { createServer } from 'node:net'
import { dirname, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const repositoryRoot = resolve(packageRoot, '../..')
const websiteRoot = resolve(repositoryRoot, 'website')
const routeName = `reference-calculator-test-${crypto.randomUUID()}`
const routeFile = resolve(websiteRoot, 'src', 'pages', `${routeName}.astro`)

let server: ReturnType<typeof Bun.serve>
let pageUrl: string

beforeAll(async () => {
  await mkdir(dirname(routeFile), { recursive: true })
  await writeFile(routeFile, `---
import { selectedSitePackageWebsite } from '../../../site-packages/reference-calculator/src/website'

const EstimateCalculator = selectedSitePackageWebsite.renderers.estimateCalculator
const ReferenceLayout = selectedSitePackageWebsite.PageLayout

const block = {
  id: 'estimate-test',
  type: 'estimateCalculator',
  data: {
    title: 'Рассчитайте стоимость',
    description: 'Предварительный расчёт по площади помещения.',
    unitPrice: 1800,
    minimumPrice: 15000,
    minimumArea: 5,
    maximumArea: 300,
  },
}
---
<ReferenceLayout>
  <main id="main-content">
    <EstimateCalculator block={block} />
  </main>
</ReferenceLayout>
`, 'utf8')

  const port = await findAvailablePort()
  const build = spawnSync(process.execPath, ['run', 'build'], {
    cwd: websiteRoot,
    encoding: 'utf8',
    env: { ...process.env },
  })
  if (build.status !== 0) {
    throw new Error(`Astro test build failed:\n${build.stdout}\n${build.stderr}`)
  }

  const outputRoot = resolve(websiteRoot, 'dist', 'client')
  server = Bun.serve({
    hostname: '127.0.0.1',
    port,
    async fetch(request) {
      const pathname = decodeURIComponent(new URL(request.url).pathname)
      const relativePath = pathname.includes('.')
        ? pathname.slice(1)
        : `${pathname.slice(1)}/index.html`
      const filePath = resolve(outputRoot, relativePath)
      if (!filePath.startsWith(`${outputRoot}${sep}`)) return new Response('Not found', { status: 404 })
      const file = Bun.file(filePath)
      return await file.exists() ? new Response(file) : new Response('Not found', { status: 404 })
    },
  })
  pageUrl = `http://127.0.0.1:${port}/${routeName}`
}, 60_000)

afterAll(async () => {
  server?.stop(true)
  await rm(routeFile, { force: true })
})

test('renders SEO copy in HTML before the calculator script', async () => {
  const html = await fetch(pageUrl).then((response) => response.text())
  const titleIndex = html.indexOf('Рассчитайте стоимость')
  const descriptionIndex = html.indexOf('Предварительный расчёт по площади помещения.')
  const scriptIndex = html.indexOf('<script')

  expect(titleIndex).toBeGreaterThan(-1)
  expect(descriptionIndex).toBeGreaterThan(titleIndex)
  expect(scriptIndex).toBeGreaterThan(descriptionIndex)
})

test('calculates both price branches with every interaction request blocked', async () => {
  const browserProcess = Bun.spawn({
    cmd: ['node', '--input-type=module', '--eval', browserInteractionScript, pageUrl],
    cwd: repositoryRoot,
    env: process.env,
    stdout: 'pipe',
    stderr: 'pipe',
  })
  const stdoutPromise = new Response(browserProcess.stdout).text()
  const stderrPromise = new Response(browserProcess.stderr).text()
  const [exitCode, stdout, stderr] = await Promise.all([
    browserProcess.exited,
    stdoutPromise,
    stderrPromise,
  ])

  expect(exitCode, stderr).toBe(0)
  expect(JSON.parse(stdout)).toEqual({
    blockedRequests: [],
    fiveSquareMetres: '15 000 ₽',
    labelledInputCount: 1,
    statusCount: 1,
    twentySquareMetres: '36 000 ₽',
  })
}, 30_000)

const browserInteractionScript = `
import { chromium } from '@playwright/test'

const browser = await chromium.launch({ headless: true })
try {
  const page = await browser.newPage()
  await page.goto(process.argv[1])
  await page.waitForLoadState('networkidle')

  const blockedRequests = []
  await page.route('**/*', async (route) => {
    blockedRequests.push(route.request().url())
    await route.abort()
  })

  const area = page.getByLabel('Площадь помещения, м²')
  const total = page.getByRole('status')
  const labelledInputCount = await area.count()
  const statusCount = await total.count()

  await area.fill('20')
  const twentySquareMetres = await total.textContent()
  await area.fill('5')
  const fiveSquareMetres = await total.textContent()

  console.log(JSON.stringify({
    blockedRequests,
    fiveSquareMetres,
    labelledInputCount,
    statusCount,
    twentySquareMetres,
  }))
} finally {
  await browser.close()
}
`

async function findAvailablePort() {
  return new Promise<number>((resolvePort, reject) => {
    const socket = createServer()
    socket.once('error', reject)
    socket.listen({ host: '127.0.0.1', port: 0 }, () => {
      const address = socket.address()
      if (!address || typeof address === 'string') {
        socket.close()
        reject(new Error('Could not reserve a browser test port'))
        return
      }
      socket.close(() => resolvePort(address.port))
    })
  })
}
